const item = $input.first().json;
let rows = item.data || [];
const subject = $('Microsoft Outlook Trigger').item.json.subject || '';
const customerIdMatch = subject.match(/\d{7}/);
const customerId = customerIdMatch ? customerIdMatch[0] : null;

if (rows.length === 0) throw new Error('Stage 1 FATAL: No inventory rows found in extracted data.');

// ── BRAND PREFIX STRIPPING (deterministic, not AI-guessed) ────────────────
const BRAND_COL_PATTERN = /^(brand|mfg|manufacturer|line|category|cat)$/i;
const ITEM_COL_PATTERN = /sku|item|part|model|mfg.*(sku|part|num)|product.*num/i;

const firstRowKeys = Object.keys(rows[0] || {});
const brandCol = firstRowKeys.find(k => BRAND_COL_PATTERN.test(k.trim()));
const itemCol = firstRowKeys.find(k => ITEM_COL_PATTERN.test(k) && k !== brandCol);

if (brandCol && itemCol) {
  rows = rows.map(row => {
    const brandVal = String(row[brandCol] ?? '').trim();
    const itemVal = String(row[itemCol] ?? '').trim();
    if (
      brandVal.length >= 2 && brandVal.length <= 6 &&
      /^[A-Za-z]+$/.test(brandVal) &&
      itemVal.toUpperCase().startsWith(brandVal.toUpperCase())
    ) {
      const stripped = itemVal.slice(brandVal.length);
      if (stripped.length >= 5) {
        return { ...row, [itemCol]: stripped };
      }
    }
    return row;
  });
}

const SYSTEM_FIELDS = new Set([
  'senderEmail','senderName','subject','receivedAt','emailBody','workflowRunId',
  'attachmentName','attachmentType','inventoryBinaryKey','hasContent',
  'contentIsBase64','rawContent','allInventoryAttachments','skippedAttachments',
  '_debug_binaryKeys','_debug_binaryData','errorType','errorMessage'
]);

// availab catches both Available and Availability
// part/num/ref are word-bounded to prevent false matches inside prose
// (e.g. "Sparta" contains "part", "prefer" contains "ref", "minimum" contains "num")
// inv/inventory added for customer files using that abbreviation for on-hand qty (e.g. a distributor "Inv" column)
// qas added for customer files using "QAS" (Quantity Available for Sale) as their on-hand column
// (e.g. Monthly_Inventory_Report_by_item.xlsx) -- word-bounded so it doesn't
// false-match inside unrelated words
const KEEP_CONTENT = /sku|item|\bpart\b|model|mfg|product|qty|quantity|on.?hand|qoh|qtyoh|upc|number|\bnum\b|\bref\b|stock|style|tqoh|availab|\boh\b|\binv\b|\binventory\b|\bqas\b/i;

// ── SMART HEADER DETECTION ────────────────────────────────────────────────
let headers = Object.keys(rows[0]).filter(k =>
  !SYSTEM_FIELDS.has(k) && KEEP_CONTENT.test(k)
);

// Force smart header scan when row 0 contains address/metadata content
const row0Values = Object.values(rows[0]).map(v => String(v ?? ''));
const row0HasMetadata = row0Values.some(v =>
  v.includes('\n') ||
  /\d{3}[-.\s]\d{3}[-.\s]\d{4}/.test(v) ||
  v.length > 60
);

if (headers.length < 2 || row0HasMetadata) {
  let foundRealHeaders = false;
  for (let i = 0; i < Math.min(rows.length, 20); i++) {
    const row = rows[i];
    const candidateHeaders = Object.values(row).filter(v =>
      v != null && KEEP_CONTENT.test(String(v))
    );
    if (candidateHeaders.length >= 2) {
      const colMap = {};
      Object.entries(row).forEach(([k, v]) => {
        if (v != null && String(v).trim() !== '') {
          colMap[k] = String(v).trim();
        }
      });

      headers = Object.values(colMap).filter(v => KEEP_CONTENT.test(v));

      const dataRows = rows.slice(i + 1).map(dataRow => {
        const remapped = {};
        Object.entries(colMap).forEach(([oldKey, newLabel]) => {
          remapped[newLabel] = dataRow[oldKey] ?? null;
        });
        return remapped;
      });

      rows = dataRows;
      foundRealHeaders = true;
      break;
    }
  }

  if (!foundRealHeaders) {
    headers = Object.keys(rows[0]).filter(k => !SYSTEM_FIELDS.has(k));
  }
}

// ── DETERMINISTIC QOH LOOKUP (JS-side, bypasses AI judgment for the number) ──
const QTY_COL_PRIORITY = [
  /\bqoh\b/i, /\bqtyoh\b/i, /\btqoh\b/i, /\bqas\b/i,
  /on.?hand/i,
  /availab/i,
  /qty.?avail|quantity.?avail/i,
  /\bqty\b|\bquantity\b/i,
  /\binv\b|\binventory\b/i,
  /\bstock\b/i
];
// '#' excluded because a true on-hand-quantity column is never labeled with a
// trailing '#' -- that convention is reserved for identifier/reference fields
// (Item #, PO #, Inventory #, Model #). Without this, a header like
// 'Inventory #' (an identifier column) satisfies /\binventory\b/i just as well
// as 'Inv' (the real quantity column) at the same priority tier, and since
// pickBestColumn takes the first array match, an earlier-positioned identifier
// column can beat the real quantity column and get treated as authoritative.
// (Root cause of the a distributor 2026-08-31 QOH corruption.)
const QTY_COL_EXCLUDE = /on.?order|backorder|back.?order|sold|shipped|committed|allocated|\bcost\b|\btotal\b|\bprice\b|#/i;
const ITEM_ID_COL_PATTERN = /sku|item|\bpart\b|model|mfg|product|style|number|\bnum\b|\bref\b/i;

function pickBestColumn(candidateHeaders, priorityList, excludePattern) {
  const eligible = candidateHeaders.filter(h => !excludePattern.test(h));
  for (const pattern of priorityList) {
    const match = eligible.find(h => pattern.test(h));
    if (match) return match;
  }
  return null;
}

const qtyCol = pickBestColumn(headers, QTY_COL_PRIORITY, QTY_COL_EXCLUDE);
const itemIdCol = headers.find(h => ITEM_ID_COL_PATTERN.test(h) && h !== qtyCol) || headers[0];

const qtyLookup = {};
if (qtyCol && itemIdCol) {
  rows.forEach(row => {
    const refKey = String(row[itemIdCol] ?? '').trim().toUpperCase();
    if (!refKey) return;
    const rawQty = row[qtyCol];
    const numQty = typeof rawQty === 'number'
      ? rawQty
      : parseFloat(String(rawQty ?? '').replace(/[^0-9.\-]/g, ''));
    if (!Number.isNaN(numQty)) {
      qtyLookup[refKey] = (qtyLookup[refKey] ?? 0) + numQty;
    }
  });
}

// ── CHUNKING (only for genuinely large submissions) ────────────────────────
// Accounts at or under CHUNK_THRESHOLD rows are unaffected — they still
// produce exactly one chunk, meaning one API call, identical to current
// behavior. Only submissions larger than any current account (Sports South
// at ~789 rows is the only one today) actually get split. This keeps every
// other customer's processing byte-for-byte unchanged.
const CHUNK_THRESHOLD = 500;
const CHUNK_SIZE = 150;

const rowChunks = [];
if (rows.length > CHUNK_THRESHOLD) {
  for (let i = 0; i < rows.length; i += CHUNK_SIZE) {
    rowChunks.push(rows.slice(i, i + CHUNK_SIZE));
  }
} else {
  rowChunks.push(rows);
}
const totalChunks = rowChunks.length;

// ── CSV HELPER ─────────────────────────────────────────────────────────────
const csvVal = (val) => {
  const s = String(val ?? '');
  return (s.includes(',') || s.includes('"') || s.includes('\n'))
    ? '"' + s.replace(/"/g, '""') + '"'
    : s;
};

// ── SYSTEM PROMPT (shared across all chunks) ───────────────────────────────
const systemPrompt = `You are an inventory data extraction specialist for Acme Manufacturing, a consumer-products manufacturer that sells through distributors and retailers. Acme sells three brands: Alpha, Bravo, and Charlie.

Extract inventory line items from the CSV and return ONLY compact JSON with no whitespace, no newlines, no indentation. No explanation, no markdown, no code fences.

ACME SKU FORMATS (fictional examples):
- Alpha products (A- prefix): A-100234-17, A-2200XY-0, A-3AB65201
- Alpha accessories (NNN-NNNN-NN pattern): 111-2222-33, 111-2300-01, 222-0001-00
- Alpha accessories (9XXXXX pattern): 912345678, 913579246, 91P123456
- Alpha accessories with a standalone suffix (valid complete SKUs, never strip the suffix): 912345678XX, 913579246YY
- Bravo products (BR prefix): BR22B4, BR22MB6, BR22CH4
- Bravo products (BX prefix): BX1218CH, BX2018BK
- Charlie products (CH prefix): CH22L1811, CH22W2111
- Legacy numeric pattern (9-digit numbers beginning with 77): 771234567. These are older part numbers that were later renumbered.
- UPCs are 12 or 13 digit numbers
- Anything else is a customer SKU

LEADING ZERO NORMALIZATION:
Some customers or systems (including ERP exports) send Acme SKUs with leading zeros prepended (e.g. 000912345678). Apply this rule:
- If a value begins with one or more leading zeros followed by a valid Acme SKU pattern, strip the leading zeros and use the result as mfrItemNumber.
- Example: 000912345678 → mfrItemNumber: 912345678
- Example: 000913579246 → mfrItemNumber: 913579246
- Always set rawItemRef to the original value exactly as it appears in the CSV.
- Do NOT strip leading zeros if the result does not match a known Acme SKU pattern.
- Do NOT apply this rule to SKUs with a standalone suffix. Those are complete SKUs and must be used as-is.

CASE NORMALIZATION:
Customer files sometimes submit Acme SKUs in lowercase or mixed case (e.g. a-100234, br22b4). Apply this rule:
- SKU matching is case-insensitive. If a rawItemRef matches an Acme SKU pattern regardless of case, populate mfrItemNumber with the value converted to UPPERCASE.
- Example: a-100234 → mfrItemNumber: A-100234
- Example: br22b4 → mfrItemNumber: BR22B4
- Always set rawItemRef to the original value exactly as it appears in the CSV. Do not uppercase rawItemRef.

RULES:
- rawItemRef: item identifier exactly as it appears in the CSV. Preserve original casing and formatting.
- mfrItemNumber: if it matches an Acme SKU pattern above (case-insensitive, after leading zero normalization if applicable), populate it with the UPPERCASE normalized value. Otherwise null.
- qtyOnHand: quantity on hand as a number. null if absent.
- upc: if the data contains a separate UPC column (12 or 13 digit number), always capture it in the upc field regardless of what is in the item number column. If the rawItemRef itself is a 12 or 13 digit UPC, also populate the upc field with it. If no UPC is present anywhere in the row, set upc to null.
- Merge duplicate rawItemRef rows by summing qtyOnHand.
- The Acme item number may appear in columns named MFG_SKU, SKU, Item Number, Item #, Model, Part Number, MFR Model #, Mfg Part #, Style, PRODUCT_NUMBER, or similar. When multiple identifier columns exist, examine the actual values in each column and use the one whose values match known Acme SKU patterns as rawItemRef and mfrItemNumber.
- The quantity on hand may appear in columns named QTYOH, QOH, Qty On Hand, Quantity on Hand, On Hand, QTY, Stock, TQOH, QAS, Available, Availability, Qty Available, Inv, Inventory, or similar. It will always be a numeric column representing stock quantities. Always identify and extract it. Never return null for qtyOnHand if a numeric quantity column exists in the data.
- If a rawItemRef value is "false", "true", "null", "undefined", or any boolean/null literal string, skip it entirely. Do not include it in output.
- If a rawItemRef value is a 12 or 13 digit number it is a UPC. Set mfrItemNumber to null and populate the upc field with it.
- SKIP any rawItemRef that contains a space. Valid Acme SKUs never contain spaces. Values like "2 CYLINDERS" or "SMALL STEEL" are category labels, not SKUs.
- SKIP any rawItemRef that is fewer than 5 characters. Valid Acme SKUs are always at least 5 characters long. Values like "R92" or "BR" are category labels, not SKUs.
- Acme SKU variants often include color, finish, or edition suffixes appended to the base SKU (for example -BK, -NI, -CH, -GLD). These are still valid Acme SKUs.

NON-STANDARD FILE LAYOUTS:
Some customer files contain summary rows, metadata, formula cells, or blank rows before the actual inventory data begins. Apply these rules:
- SKIP any row where the SKU/part number field is empty, blank, or contains non-SKU text such as labels (e.g. "Cost Value:", "YTD Sales:", "MFG:"), formula strings (e.g. "=SUM(...)"), or summary descriptions.
- SKIP any row where every meaningful field is null or empty.
- A valid inventory row must have a non-empty SKU or part number value. Quantity on hand may be 0 or null. That is acceptable as long as the SKU is present.
- DO NOT include summary totals, subtotals, or grand total rows as inventory items.

Return exactly this compact JSON structure:
{"items":[{"rawItemRef":"<string>","mfrItemNumber":"<string or null>","qtyOnHand":<number or null>,"upc":"<12 or 13 digit string, or null>"}]}`;

// ── BUILD ONE OUTPUT ITEM PER CHUNK ────────────────────────────────────────
const outputItems = rowChunks.map((chunkRows, chunkIdx) => {
  const csvLines = [headers.join(',')];
  chunkRows.forEach(row => {
    const line = headers.map(h => csvVal(row[h])).join(',');
    csvLines.push(line);
  });
  const csvContent = csvLines.join('\n');
  const MAX_CHARS = 80000;
  const truncated = csvContent.length > MAX_CHARS;
  const contentForPrompt = truncated ? csvContent.substring(0, MAX_CHARS) + '\n[TRUNCATED]' : csvContent;

  const userPrompt = totalChunks > 1
    ? `Extract all inventory line items from the following CSV data submitted by a Acme customer.
Sender: ${item.senderEmail}
Subject: ${item.subject}
Chunk: ${chunkIdx + 1} of ${totalChunks}
Rows in this chunk: ${chunkRows.length}${truncated ? ' (TRUNCATED)' : ''}
--- CONTENT START ---
${contentForPrompt}
--- CONTENT END ---
Return ONLY compact JSON. No other text.`
    : `Extract all inventory line items from the following CSV data submitted by a Acme customer.
Sender: ${item.senderEmail}
Subject: ${item.subject}
Rows: ${chunkRows.length}${truncated ? ' (TRUNCATED)' : ''}
--- CONTENT START ---
${contentForPrompt}
--- CONTENT END ---
Return ONLY compact JSON. No other text.`;

  return {
    json: {
      ...item,
      customerId: customerId,
      chunkIndex: chunkIdx,
      totalChunks: totalChunks,
      qtyLookup: qtyLookup,
      qtyLookupMeta: { qtyCol, itemIdCol },
      apiMessages: [{ role: 'user', content: userPrompt }],
      apiSystemPrompt: [
        {
          type: 'text',
          text: systemPrompt,
          cache_control: { type: 'ephemeral' }
        }
      ]
    }
  };
});

return outputItems;

const item = $input.item.json;
const today = new Date().toISOString().split('T')[0];
const customerId = $('Build AI Parser Prompt').item.json.customerId ?? null;
const qtyLookup = $('Build AI Parser Prompt').item.json.qtyLookup ?? {};
const chunkIndex = $('Build AI Parser Prompt').item.json.chunkIndex ?? 0;
const totalChunks = $('Build AI Parser Prompt').item.json.totalChunks ?? 1;
const outlookTrigger = $('Microsoft Outlook Trigger').item.json;
const senderEmail = outlookTrigger.from?.emailAddress?.address ?? null;
const senderName = outlookTrigger.from?.emailAddress?.name ?? null;
const subject = outlookTrigger.subject ?? null;
const receivedAt = outlookTrigger.receivedDateTime ?? null;
const workflowRunId = $('Build AI Parser Prompt').item.json.workflowRunId ?? null;
let claudeText = '';
try {
  const content = item.content ?? [];
  claudeText = content
    .filter(c => c.type === 'text')
    .map(c => c.text)
    .join('')
    .trim();
} catch(e) {
  throw new Error('Stage 1 FATAL: Could not read Claude API response content. Raw: ' + JSON.stringify(item).substring(0, 500));
}

let parsed = null;
try {
  const cleaned = claudeText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
  parsed = JSON.parse(cleaned);
} catch(e) {
  throw new Error(`Stage 1 FATAL: Claude response was not valid JSON (chunk ${chunkIndex + 1} of ${totalChunks}). Response preview: ` + claudeText.substring(0, 300));
}

if (!parsed.items || !Array.isArray(parsed.items)) {
  throw new Error(`Stage 1 FATAL: Claude response missing items array (chunk ${chunkIndex + 1} of ${totalChunks}).`);
}
if (parsed.items.length === 0) {
  throw new Error(`Stage 1 FATAL: Claude returned zero items (chunk ${chunkIndex + 1} of ${totalChunks}).`);
}

const CONFIDENCE_THRESHOLD = 0.75;
const warnings = [];
const mergedItems = new Map();

for (const rawItem of parsed.items) {
  if (!rawItem.rawItemRef) {
    warnings.push('Item missing rawItemRef — skipping');
    continue;
  }

  if (typeof rawItem.qtyOnHand === 'string') {
    rawItem.qtyOnHand = parseFloat(rawItem.qtyOnHand.replace(/[^0-9.]/g, '')) || null;
  }

  let itemRefType = 'customer-sku';
  if (rawItem.mfrItemNumber) {
    const sku = rawItem.mfrItemNumber.toUpperCase();
    if (/^(BR|BX)/.test(sku)) itemRefType = 'brand-b-sku';
    else if (/^CH/.test(sku)) itemRefType = 'brand-c-sku';
    else if (/^\d{3}-\d{4}-\d{2}$/.test(sku)) itemRefType = 'brand-a-sku';
    else itemRefType = 'brand-a-sku';
  } else if (/^\d{12,13}$/.test(rawItem.rawItemRef.replace(/\s/g, ''))) {
    itemRefType = 'upc';
  }

  const itemResolved = rawItem.mfrItemNumber !== null && rawItem.mfrItemNumber !== undefined;
  const resolutionConfidence = itemResolved ? 0.95 : 0.0;
  const resolutionSource = itemResolved ? 'ai-direct' : null;

  if (resolutionConfidence < CONFIDENCE_THRESHOLD && itemResolved) {
    rawItem.mfrItemNumber = null;
    warnings.push(rawItem.rawItemRef + ': low confidence — flagged for manual review');
  }

  const lookupKey = rawItem.rawItemRef.trim().toUpperCase();
  const lookedUpQty = qtyLookup[lookupKey];
  const finalQty = lookedUpQty !== undefined ? lookedUpQty : (rawItem.qtyOnHand ?? null);

  const fullItem = {
    lineNumber: 0,
    rawItemRef: rawItem.rawItemRef,
    itemRefType,
    mfrItemNumber: rawItem.mfrItemNumber ?? null,
    upc: rawItem.upc ?? (itemRefType === 'upc' ? rawItem.rawItemRef : null),
    customerPartNum: itemRefType === 'customer-sku' ? rawItem.rawItemRef : null,
    qtyOnHand: finalQty,
    uom: 'EA',
    itemResolved,
    resolutionSource,
    resolutionConfidence,
    parseNotes: null
  };

  const key = rawItem.rawItemRef.trim().toUpperCase();
  if (mergedItems.has(key)) {
    const existing = mergedItems.get(key);
    const combinedQty = (existing.qtyOnHand ?? 0) + (fullItem.qtyOnHand ?? 0);
    existing.qtyOnHand = combinedQty;
    existing.parseNotes = 'Merged duplicate — summed qtyOnHand = ' + combinedQty;
    warnings.push(rawItem.rawItemRef + ': duplicate merged');
  } else {
    mergedItems.set(key, fullItem);
  }
}

const finalItems = Array.from(mergedItems.values());
finalItems.forEach((it, idx) => { it.lineNumber = idx + 1; });

const resolvedCount = finalItems.filter(it => it.itemResolved).length;
const parseConfidence = finalItems.length > 0
  ? Math.round((resolvedCount / finalItems.length) * 100) / 100
  : 0;

const manualReviewItems = finalItems.filter(it => !it.itemResolved);
const needsManualReview = manualReviewItems.length > 0;

const workingObject = {
  envelope: {
    senderEmail:     senderEmail,
    senderName:      senderName,
    subject:         subject,
    receivedAt:      receivedAt,
    attachmentName:  item.attachmentName,
    attachmentType:  item.attachmentType,
    rawContent:      null,
    parseMethod:     'ai-claude',
    parseConfidence,
    workflowRunId:   workflowRunId,
    customerId:      customerId
  },
  customer:         null,
  items:            finalItems,
  openOrders:       [],
  availability:     [],
  topItems:         [],
  comparison:       null,
  salesHistory:     null,
  aiRecommendation: null,
  _meta: {
    stage1CompletedAt:    new Date().toISOString(),
    itemCount:            finalItems.length,
    reportDate:           today,
    manualReviewRequired: needsManualReview,
    manualReviewCount:    manualReviewItems.length,
    warnings:             warnings,
    processingNotes:      warnings.length > 0 ? warnings.join(' | ') : null,
    chunkIndex,
    totalChunks
  }
};

return { json: workingObject };

// Search across all items for the inventory binary attachment
// (handles emails with multiple attachments e.g. signature images)
const allItems = $input.all();
let inventoryBinaryKey = null;
let binary = null;
let matchedItem = null;

for (const it of allItems) {
  const b = it.binary ?? {};
  const key = Object.keys(b).find(k =>
    (b[k].mimeType || '').includes('spreadsheetml') ||
    (b[k].mimeType || '').includes('excel') ||
    (b[k].mimeType || '').includes('csv') ||
    (b[k].mimeType || '').includes('pdf') ||
    ((b[k].mimeType || '').includes('octet-stream') && (
      (b[k].fileName || '').toLowerCase().endsWith('.xlsx') ||
      (b[k].fileName || '').toLowerCase().endsWith('.xls') ||
      (b[k].fileName || '').toLowerCase().endsWith('.csv') ||
      (b[k].fileName || '').toLowerCase().endsWith('.pdf')
    ))
  );
  if (key) {
    inventoryBinaryKey = key;
    binary = b;
    matchedItem = it;
    break;
  }
}

if (!inventoryBinaryKey) {
  throw new Error('Stage 1 FATAL: No inventory attachment found in email.');
}

return {
  json: {
    ...matchedItem.json,
    inventoryBinaryKey: inventoryBinaryKey,
    attachmentName: binary[inventoryBinaryKey].fileName,
    attachmentType: binary[inventoryBinaryKey].mimeType
  },
  binary: {
    inventory_file: binary[inventoryBinaryKey]
  }
};

const binary = $input.item.binary || {};
const inventoryBinaryKey = Object.keys(binary).find(k =>
  (binary[k].mimeType || '').includes('spreadsheetml') ||
  (binary[k].mimeType || '').includes('excel') ||
  (binary[k].mimeType || '').includes('csv') ||
  (binary[k].mimeType || '').includes('pdf') ||
  ((binary[k].mimeType || '').includes('octet-stream') && (
    (binary[k].fileName || '').toLowerCase().endsWith('.xlsx') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.xls') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.csv') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.pdf')
  ))
);
if (!inventoryBinaryKey) {
  throw new Error('Stage 1 FATAL: No inventory attachment found in email.');
}
return {
  json: {
    ...$input.item.json,
    inventoryBinaryKey: inventoryBinaryKey,
    attachmentName: binary[inventoryBinaryKey].fileName,
    attachmentType: binary[inventoryBinaryKey].mimeType
  },
  binary: {
    inventory_file: binary[inventoryBinaryKey]
  }
};

const binary = $input.item.binary || {};
const inventoryBinaryKey = Object.keys(binary).find(k =>
  (binary[k].mimeType || '').includes('spreadsheetml') ||
  (binary[k].mimeType || '').includes('excel') ||
  (binary[k].mimeType || '').includes('csv') ||
  (binary[k].mimeType || '').includes('pdf') ||
  (binary[k].mimeType || '').includes('octet-stream') && (
    (binary[k].fileName || '').toLowerCase().endsWith('.xlsx') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.xls') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.csv') ||
    (binary[k].fileName || '').toLowerCase().endsWith('.pdf')
  )
);
if (!inventoryBinaryKey) {
  throw new Error('Stage 1 FATAL: No inventory attachment found in email.');
}

let attachmentBinary = binary[inventoryBinaryKey];

// Helpers for CSV table detection (quote-aware)
function splitRecords(text) {
  const records = [];
  let cur = '';
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '"') {
      inQuotes = !inQuotes;
      cur += ch;
    } else if (ch === '\n' && !inQuotes) {
      records.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  records.push(cur);
  return records.filter(r => r.trim() !== '');
}

function countFields(record) {
  let n = 1;
  let inQuotes = false;
  for (let i = 0; i < record.length; i++) {
    const ch = record[i];
    if (ch === '"') inQuotes = !inQuotes;
    else if (ch === ',' && !inQuotes) n++;
  }
  return n;
}

// Fix for malformed source files (seen in a distributor/agency exports like
// KB0040103313204w.csv) where every row is terminated with a doubled
// carriage return (\r\r\n) instead of a normal line ending. This confuses
// the downstream CSV parser's newline auto-detection -- it starts
// treating a lone \r as the row separator, which splits real rows in
// half and eventually throws "Invalid Opening Quote" when it hits a
// quote character right after a stray leftover \n. Fix: collapse
// \r\r\n -> \n, then normalize any remaining \r\n or lone \r the same
// way, before the CSV extraction node ever sees the file.
//
// Additionally (added 2026-09-29): some agency CSVs (e.g. the weekly SMGA
// report) carry a variable number of title/banner lines above the real
// header row, and sometimes footer lines below the table. csv-parse
// enforces one uniform record width, so those lines make Extract from File
// throw "Invalid Record Length". XLSX/XLS files don't hit this because
// SheetJS tolerates ragged rows and Build AI Parser Prompt's smart header
// detection repairs the header. For CSVs we trim instead: the table width is
// the most common field count, and only records from the first to the last
// record of that width are kept.
const isCsv = (attachmentBinary.mimeType || '').includes('csv') ||
  (attachmentBinary.fileName || '').toLowerCase().endsWith('.csv');

if (isCsv) {
  const buffer = await this.helpers.getBinaryDataBuffer($itemIndex, inventoryBinaryKey);
  let text = buffer.toString('latin1'); // latin1 preserves byte values 1:1, safe for re-encoding

  text = text
    .replace(/^\u00EF\u00BB\u00BF/, '') // UTF-8 BOM as seen through latin1
    .replace(/\r\r\n/g, '\n')
    .replace(/\r\n/g, '\n')
    .replace(/\r/g, '\n');

  const records = splitRecords(text);
  if (records.length === 0) {
    throw new Error('Stage 1 FATAL: CSV attachment contains no non-empty records.');
  }

  const counts = records.map(countFields);

  // Modal field count (ties resolve to the wider count)
  const freq = {};
  counts.forEach(c => { freq[c] = (freq[c] || 0) + 1; });
  let width = 0;
  let best = -1;
  for (const [c, f] of Object.entries(freq)) {
    const cn = Number(c);
    if (f > best || (f === best && cn > width)) {
      best = f;
      width = cn;
    }
  }

  const first = counts.findIndex(c => c === width);
  let last = -1;
  for (let k = counts.length - 1; k >= 0; k--) {
    if (counts[k] === width) { last = k; break; }
  }

  // Any record inside the table body with the wrong width -> fail loudly with detail
  const bad = [];
  for (let k = first; k <= last; k++) {
    if (counts[k] !== width) {
      bad.push({ record: k + 1, fields: counts[k], text: records[k].slice(0, 200) });
    }
  }
  if (bad.length > 0) {
    throw new Error(
      'Stage 1 FATAL: CSV table width is ' + width + ' fields but ' + bad.length +
      ' record(s) inside the table differ. First 5: ' + JSON.stringify(bad.slice(0, 5))
    );
  }

  const cleaned = records.slice(first, last + 1).join('\n') + '\n';

  attachmentBinary = await this.helpers.prepareBinaryData(
    Buffer.from(cleaned, 'latin1'),
    attachmentBinary.fileName,
    attachmentBinary.mimeType
  );
}

return {
  json: {
    ...$input.item.json,
    inventoryBinaryKey: inventoryBinaryKey,
    attachmentName: binary[inventoryBinaryKey].fileName,
    attachmentType: binary[inventoryBinaryKey].mimeType
  },
  binary: {
    inventory_file: attachmentBinary
  }
};

const binary = $input.item.binary || {};

