}));

// ── FIX: MGD2/Family values come from a fixed-width SAP field and arrive
// with trailing whitespace (e.g. "OTHERS" + 54 trailing spaces). The old
// comparator checked `a.mgd2 === 'OTHERS'` which never matched, so the
// OTHERS/ACCESSO group never got pushed to ZZZZZ and instead sorted
// alphabetically among real categories. Trim + uppercase before comparing.
summaryItems.sort((a, b) => {
  const mgd2ARaw = (a.mgd2 || '').trim().toUpperCase();
  const mgd2BRaw = (b.mgd2 || '').trim().toUpperCase();
  const pushToBottom = (v) => (!v || v === 'OTHERS' || v === 'ACCESSORIES US');
  const mgd2A = pushToBottom(mgd2ARaw) ? 'ZZZZZ' : mgd2ARaw;
  const mgd2B = pushToBottom(mgd2BRaw) ? 'ZZZZZ' : mgd2BRaw;
  if (mgd2A !== mgd2B) return mgd2A.localeCompare(mgd2B);

  const famARaw = (a.family || '').trim().toUpperCase();
  const famBRaw = (b.family || '').trim().toUpperCase();
  const famA = (!famARaw || famARaw === 'OTHERS') ? 'ZZZZZ' : famARaw;
  const famB = (!famBRaw || famBRaw === 'OTHERS') ? 'ZZZZZ' : famBRaw;
  if (famA !== famB) return famA.localeCompare(famB);

  const matA  = a.mfrItemNumber || a.rawItemRef || '';
  const matB  = b.mfrItemNumber || b.rawItemRef || '';
  return matA.localeCompare(matB);
});

