}

// ── HELPER: render a recommendation section ───────────────────────────────
function renderRecSection(sheet, lines, sectionTitle, headerColor, isAvailableNow) {
  const colCount = 16;

  const titleRow = sheet.addRow([]);
  titleRow.getCell(1).value = sectionTitle;
  titleRow.height = 22;
  for (let c = 1; c <= colCount; c++) {
    titleRow.getCell(c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: headerColor } };
  }
  titleRow.getCell(1).font = { bold: true, color: { argb: WHITE }, name: 'Arial', size: 11 };
  titleRow.getCell(1).alignment = { vertical: 'middle', indent: 1 };

  if (lines.length === 0) {
    const emptyRow = sheet.addRow([]);
    emptyRow.getCell(1).value = 'No items in this category.';
    emptyRow.getCell(1).font  = { italic: true, name: 'Arial', size: 10, color: { argb: 'FF999999' } };
    emptyRow.getCell(1).fill  = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT_GRAY } };
    emptyRow.height = 18;
    sheet.addRow([]).height = 8;
    return;
  }

  let lastSF   = null;
  let rowIndex = 0;

  lines.forEach(function(line) {
    const sf = line.subFamily || 'OTHER';
    if (sf !== lastSF) {
      const sfRow = sheet.addRow([]);
      sfRow.getCell(1).value = sf;
      sfRow.height = 18;
      for (let c = 1; c <= colCount; c++) {
        sfRow.getCell(c).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: LIGHT_GRAY } };
      }
      sfRow.getCell(1).font = { bold: true, name: 'Arial', size: 10 };
      sfRow.getCell(1).alignment = { horizontal: 'left', vertical: 'middle', indent: 1 };
      lastSF = sf;
    }

    const itemData       = itemLookup[line.itemNo] ?? {};
    const customerQOH    = itemData.customerQOH     ?? 0;
    const shipped12mo    = itemData.totalShipped12mo ?? 0;
    const soldThrough    = Math.max(0, shipped12mo - customerQOH);
    const weeklyVelocity = soldThrough > 0 ? +(soldThrough / 52).toFixed(2) : 0;
    const currentWOS     = weeklyVelocity > 0 ? +(customerQOH / weeklyVelocity).toFixed(1) : 0;
    const targetWOS      = targetWeeksOnHand;
    const targetQty      = weeklyVelocity > 0 ? Math.ceil(targetWOS * weeklyVelocity) : 0;
    const onOrderQty     = itemLookup[line.itemNo]?.openOrderQty ?? 0;

    const isUrgent  = isAvailableNow && weeklyVelocity > 10 && currentWOS < 2;
    const fillColor = isUrgent ? NEON_GREEN : (rowIndex % 2 === 0 ? WHITE : ALT_ROW);

    const row = sheet.addRow([]);
    row.getCell(1).value  = line.itemNo        || '';
    row.getCell(2).value  = line.upc || itemLookup[line.itemNo]?.upc || '';
    row.getCell(3).value  = line.description   || '';
    row.getCell(4).value  = line.brand         || '';
    row.getCell(5).value  = line.subFamily     || '';
    row.getCell(6).value  = line.mgd2          || '';
    row.getCell(7).value  = Number(line.casePack)       || 0;
    row.getCell(8).value  = customerQOH;
    row.getCell(9).value  = weeklyVelocity;
    row.getCell(10).value = currentWOS;
    row.getCell(11).value = targetWOS;
    row.getCell(12).value = targetQty;
    row.getCell(13).value = onOrderQty;
    row.getCell(14).value = Number(line.recommendedQty) || 0;
    row.getCell(15).value = Number(line.netSellPrice)   || 0;
    row.getCell(16).value = line.rationale     || '';
    row.height = 18;

    for (let c = 1; c <= colCount; c++) {
      const cell = row.getCell(c);
      cell.font  = { name: 'Arial', size: 10 };
      cell.fill  = { type: 'pattern', pattern: 'solid', fgColor: { argb: fillColor } };
      cell.border = { bottom: { style: 'hair', color: { argb: 'FFEEEEEE' } } };
      cell.alignment = { vertical: 'middle' };
    }
    row.getCell(7).alignment  = { horizontal: 'center', vertical: 'middle' };
    row.getCell(8).alignment  = { horizontal: 'center', vertical: 'middle' };
    row.getCell(9).alignment  = { horizontal: 'center', vertical: 'middle' };
    row.getCell(9).numFmt     = '0.00';
    row.getCell(10).alignment = { horizontal: 'center', vertical: 'middle' };
    row.getCell(10).numFmt    = '0.0';
    row.getCell(11).alignment = { horizontal: 'center', vertical: 'middle' };
    row.getCell(12).alignment = { horizontal: 'center', vertical: 'middle' };
    row.getCell(13).alignment = { horizontal: 'center', vertical: 'middle' };
    row.getCell(14).alignment = { horizontal: 'center', vertical: 'middle' };
    row.getCell(15).numFmt    = '"$"#,##0.00';
    row.getCell(15).alignment = { horizontal: 'right',  vertical: 'middle' };

    // Rec. Qty — always gold regardless of row highlight
    row.getCell(14).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: BRAND_ACCENT } };
    row.getCell(14).font = { name: 'Arial', size: 10, bold: true, color: { argb: WHITE } };

    // Curr. WOS — always applied even on neon green rows
   if (currentWOS < 2) {
      row.getCell(10).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFC00000' } };
      row.getCell(10).font = { name: 'Arial', size: 10, bold: true, color: { argb: WHITE } };
    } else if (currentWOS < 5) {
      row.getCell(10).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFC7CE' } };
      row.getCell(10).font = { name: 'Arial', size: 10, color: { argb: 'FF9C0006' } };
    }

    // Wkly Vel. — always applied even on neon green rows
    if (weeklyVelocity > 6) {
      row.getCell(9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF375623' } };
      row.getCell(9).font = { name: 'Arial', size: 10, bold: true, color: { argb: WHITE } };
    } else if (weeklyVelocity > 2) {
      row.getCell(9).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFC6EFCE' } };
      row.getCell(9).font = { name: 'Arial', size: 10, color: { argb: 'FF276221' } };
    }

    rowIndex++;
  });

  sheet.addRow([]).height = 8;
}

