// Convert UTC (Z) timestamp to US Eastern time, formatted as
// "YYYY-MM-DD HH:mm:ss". Uses Intl so EST/EDT is handled automatically
// based on the date (no manual offset math, no DST bugs).
function toEasternString(isoString) {
  const d = new Date(isoString);
  if (isNaN(d.getTime())) return isoString; // fallback if unparseable

  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false
  }).formatToParts(d);

  const get = (type) => parts.find(p => p.type === type)?.value;
  return `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')}:${get('second')}`;
}

const rawReceivedAt = (envelope.receivedAt ?? new Date().toISOString()).replace(/^=/, '');
const submittedAtEastern = toEasternString(rawReceivedAt);

