    'Sender Email':    envelope.senderEmail?.replace(/^=/, '')       ?? '',
    'Customer Name':   stage2.customer.customerName?.replace(/^=/, '') ?? '',
    'Customer ID':     String(stage2.customer.customerId ?? '').replace(/^=/, ''),
    'Submitted At':    submittedAtEastern,
    'Items Count':     stage2.items.length ?? 0,
    'Workflow Run ID': envelope.workflowRunId?.replace(/^=/, '')     ?? ''
  }
