const workingObject = $('Build UPC Lookup Query').item.json;
const lookupRows = $input.all().map(r => r.json).filter(r => r.material && r.upc);
const upcToSku = new Map(lookupRows.map(r => [r.upc, r.material]));

// Build a map of UPC → qtyOnHand from the submission
// so we can correctly assign QOH to the resolved Acme SKU
const upcToQoh = new Map();
for (const it of workingObject.items) {
  if (it.upc && it.qtyOnHand !== null && it.qtyOnHand !== undefined) {
    // Take the highest QOH if the same UPC appears on multiple items
    const existing = upcToQoh.get(it.upc);
    if (existing === undefined || it.qtyOnHand > existing) {
      upcToQoh.set(it.upc, it.qtyOnHand);
    }
  }
}

// Resolve items and deduplicate by resolved mfrItemNumber
// keeping QOH from the UPC map
const resolvedMap = new Map();

for (const it of workingObject.items) {
  const resolveViaUpcRef = it.itemRefType === 'upc' && !it.itemResolved && upcToSku.has(it.upc);
  const resolveViaUpcCol = it.itemRefType === 'customer-sku' && !it.itemResolved && it.upc && upcToSku.has(it.upc);

  if (resolveViaUpcRef || resolveViaUpcCol) {
    const sku = upcToSku.get(it.upc);
    const qoh = upcToQoh.get(it.upc) ?? it.qtyOnHand ?? null;

    if (resolvedMap.has(sku)) {
      // Already have this SKU — merge QOH if this one is higher
      const existing = resolvedMap.get(sku);
      if (qoh !== null && (existing.qtyOnHand === null || qoh > existing.qtyOnHand)) {
        existing.qtyOnHand = qoh;
      }
    } else {
      resolvedMap.set(sku, {
        ...it,
        mfrItemNumber: sku,
        itemRefType: 'brand-a-sku',
        itemResolved: true,
        resolutionSource: 'upc-lookup',
        resolutionConfidence: 0.95,
        qtyOnHand: qoh,
        parseNotes: (it.parseNotes ? it.parseNotes + ' | ' : '') + 'Resolved via UPC decoder (materials)'
      });
    }
  } else {
    // Not UPC-resolved — keep as-is but check for mfrItemNumber collision
    // with something we already resolved via UPC
    const key = it.mfrItemNumber ?? it.rawItemRef;
    if (!resolvedMap.has(key)) {
      resolvedMap.set(key, it);
    }
  }
}

const finalItems = Array.from(resolvedMap.values());

const resolvedCount = finalItems.filter(it => it.itemResolved).length;
const parseConfidence = finalItems.length > 0
  ? Math.round((resolvedCount / finalItems.length) * 100) / 100
  : 0;
const manualReviewItems = finalItems.filter(it => !it.itemResolved);
const needsManualReview = manualReviewItems.length > 0;

return {
  json: {
    ...workingObject,
    items: finalItems,
    envelope: { ...workingObject.envelope, parseConfidence },
    _meta: {
      ...workingObject._meta,
      manualReviewRequired: needsManualReview,
      manualReviewCount: manualReviewItems.length
    }
  }
};

const workingObject = $input.item.json;
const escUpc = (v) => String(v).replace(/'/g, "''");

// Include unresolved UPC items AND unresolved customer-sku items that have
// a UPC value captured from a separate UPC column in the submission file
const upcItems = workingObject.items.filter(it =>
  !it.itemResolved && it.upc &&
  (it.itemRefType === 'upc' || it.itemRefType === 'customer-sku')
);

const upcList = [...new Set(upcItems.map(it => escUpc(it.upc)))];

const sql = upcList.length > 0
  ? `SELECT material, upc FROM materials WHERE upc IN ('${upcList.join("','")}');`
  : `SELECT NULL AS material, NULL AS upc WHERE FALSE;`;

return { json: { ...workingObject, sql } };

const workingObject = $input.item.json;
const escVal = (v) => String(v).replace(/'/g, "''");

// Legacy part numbers (older numbering that was later renumbered) are sometimes carried over by
// customers as old stock, but the live materials master only has the current prefixed version of
// the same item. Flag these so we also query the prefixed candidate, not just the literal legacy
// string, which would never match on its own.
const LEGACY_PREFIX_PATTERN = /^77[0-9A-Z]{4,8}$/i;

// Some customers append a trailing "FG" (finished goods) tag to Acme SKUs
// (e.g. A-100234FG, BR22B6FG). The live master carries the SKU
// without it, so also query the FG-stripped candidate. Fallback only --
// the literal string is always queried too.
const FG_SUFFIX_PATTERN = /^(.{5,})FG$/i;

const skuItems = workingObject.items.filter(it =>
  it.mfrItemNumber && ['brand-a-sku','brand-b-sku','brand-c-sku'].includes(it.itemRefType)
);

const flatSkuSet = new Set();
skuItems.forEach(it => {
  const flat = it.mfrItemNumber.replace(/-/g, '').toUpperCase();
  flatSkuSet.add(escVal(flat));
  if (LEGACY_PREFIX_PATTERN.test(flat)) {
    flatSkuSet.add(escVal('N' + flat));
  }
  const fgMatch = flat.match(FG_SUFFIX_PATTERN);
  if (fgMatch) {
    flatSkuSet.add(escVal(fgMatch[1]));
  }
});
const flatSkus = [...flatSkuSet];

const skuSql = flatSkus.length > 0
  ? `SELECT material, REPLACE(UPPER(material), '-', '') AS flat_key FROM materials WHERE REPLACE(UPPER(material), '-', '') IN ('${flatSkus.join("','")}');`
  : `SELECT NULL AS material, NULL AS flat_key WHERE FALSE;`;

return { json: { ...workingObject, skuSql } };

const workingObject = $('Build SKU Verification Query').item.json;
const rows = $input.all().map(r => r.json).filter(r => r.material && r.flat_key);
const flatToReal = new Map(rows.map(r => [r.flat_key, r.material]));

// Legacy part numbers (older numbering that was later renumbered) are sometimes carried over by
// customers as old stock, but the live materials master only has the current prefixed version of
// the same item. Flag these so we also query the prefixed candidate, not just the literal legacy
// string, which would never match on its own.
const LEGACY_PREFIX_PATTERN = /^77[0-9A-Z]{4,8}$/i;

// Trailing "FG" (finished goods) tag some customers append to Acme SKUs,
// e.g. A-100234FG -> A-100234. Fallback only: tried after the direct
// match and the legacy-prefix remap fail.
const FG_SUFFIX_PATTERN = /^(.{5,})FG$/i;

const finalItems = workingObject.items.map(it => {
  // UPC-resolved items were already confirmed against materials via
  // UPC lookup (resolutionConfidence 0.95, resolutionSource 'upc-lookup').
  // Re-running a SKU-format check against them is redundant and can
  // incorrectly downgrade a valid resolution if the flattened SKU string
  // doesn't match materials' formatting — so they're exempt here.
  if (it.resolutionSource === 'upc-lookup') {
    return it;
  }

  if (it.mfrItemNumber && ['brand-a-sku','brand-b-sku','brand-c-sku'].includes(it.itemRefType)) {
    const flat = it.mfrItemNumber.replace(/-/g, '').toUpperCase();

    if (flatToReal.has(flat)) {
      const realSku = flatToReal.get(flat);
      if (realSku !== it.mfrItemNumber) {
        return {
          ...it,
          mfrItemNumber: realSku,
          parseNotes: (it.parseNotes ? it.parseNotes + ' | ' : '') + `SKU reformatted to match materials (${realSku})`
        };
      }
      return it;
    }

    // Direct match failed -- if this looks like a legacy-prefix model number, try the current
    // prefixed equivalent before giving up and flagging the item for manual review.
    if (LEGACY_PREFIX_PATTERN.test(flat)) {
      const legacyFlat = 'N' + flat;
      if (flatToReal.has(legacyFlat)) {
        const realSku = flatToReal.get(legacyFlat);
        return {
          ...it,
          mfrItemNumber: realSku,
          itemRefType: 'brand-b-sku',
          parseNotes: (it.parseNotes ? it.parseNotes + ' | ' : '') + `Legacy-prefix model number remapped to current SKU (${realSku})`
        };
      }
    }

    // Still no match -- try stripping a trailing customer-added "FG" tag.
    const fgMatch = flat.match(FG_SUFFIX_PATTERN);
    if (fgMatch && flatToReal.has(fgMatch[1])) {
      const realSku = flatToReal.get(fgMatch[1]);
      return {
        ...it,
        mfrItemNumber: realSku,
        parseNotes: (it.parseNotes ? it.parseNotes + ' | ' : '') + `Trailing "FG" suffix stripped to match materials (${realSku})`
      };
    }

    return {
      ...it,
      itemResolved: false,
      resolutionConfidence: 0.0,
      resolutionSource: null,
      parseNotes: (it.parseNotes ? it.parseNotes + ' | ' : '') + 'SKU not found in materials master — flagged for manual review'
    };
  }
  return it;
});

const resolvedCount = finalItems.filter(it => it.itemResolved).length;
const parseConfidence = finalItems.length > 0 ? Math.round((resolvedCount / finalItems.length) * 100) / 100 : 0;
const manualReviewItems = finalItems.filter(it => !it.itemResolved);
const needsManualReview = manualReviewItems.length > 0;

return {
  json: {
    ...workingObject,
    items: finalItems,
    envelope: { ...workingObject.envelope, parseConfidence },
    _meta: { ...workingObject._meta, manualReviewRequired: needsManualReview, manualReviewCount: manualReviewItems.length }
  }
};

// This node must run in "Run Once for All Items" mode — it needs to see
// every chunk's parsed output at once to merge them into a single working
// object before the rest of Stage 1 proceeds. For accounts under the
// chunking threshold, this receives exactly 1 item and simply passes it
// through unchanged (the merge logic is a no-op with only one chunk).
const allChunks = $input.all().map(i => i.json);
if (allChunks.length === 0) throw new Error('Combine Parsed Chunks FATAL: no chunk data received.');

// ── PASS 1: merge by raw submitted text ────────────────────────────────────
// Catches exact duplicate rows within/across chunks (same rawItemRef
// appearing more than once in the source file).
const mergedByRawRef = new Map();
for (const chunk of allChunks) {
  for (const it of (chunk.items ?? [])) {
    const key = it.rawItemRef.trim().toUpperCase();
    if (mergedByRawRef.has(key)) {
      const existing = mergedByRawRef.get(key);
      const combinedQty = (existing.qtyOnHand ?? 0) + (it.qtyOnHand ?? 0);
      existing.qtyOnHand = combinedQty;
      existing.parseNotes = (existing.parseNotes ? existing.parseNotes + ' | ' : '') +
        'Merged duplicate across chunks — summed qtyOnHand = ' + combinedQty;
    } else {
      mergedByRawRef.set(key, { ...it });
    }
  }
}
const itemsAfterRawMerge = Array.from(mergedByRawRef.values());

// ── PASS 2: merge by RESOLVED mfrItemNumber ─────────────────────────────
// Two different raw source rows (e.g. two internal listing codes a
// distributor uses for the same physical item) can independently resolve
// to the identical final Acme SKU. Pass 1 can't catch this since the raw
// text differs — this pass catches it after resolution. Items with no
// resolved SKU (itemResolved: false) are left alone here — they're
// genuinely distinct unresolved customer entries and must not be merged
// together just because they share a null mfrItemNumber.
const mergedByResolvedSku = new Map();
const unresolvedItems = [];

for (const it of itemsAfterRawMerge) {
  if (!it.mfrItemNumber) {
    unresolvedItems.push(it);
    continue;
  }
  const skuKey = it.mfrItemNumber.trim().toUpperCase();
  if (mergedByResolvedSku.has(skuKey)) {
    const existing = mergedByResolvedSku.get(skuKey);
    const combinedQty = (existing.qtyOnHand ?? 0) + (it.qtyOnHand ?? 0);
    existing.qtyOnHand = combinedQty;
    existing.parseNotes = (existing.parseNotes ? existing.parseNotes + ' | ' : '') +
      `Merged duplicate resolving to same SKU (raw: ${it.rawItemRef} -> ${skuKey}) — summed qtyOnHand = ${combinedQty}`;
  } else {
    mergedByResolvedSku.set(skuKey, { ...it });
  }
}

const finalItems = [...mergedByResolvedSku.values(), ...unresolvedItems];
finalItems.forEach((it, idx) => { it.lineNumber = idx + 1; });

const resolvedCount = finalItems.filter(it => it.itemResolved).length;
const parseConfidence = finalItems.length > 0
  ? Math.round((resolvedCount / finalItems.length) * 100) / 100
  : 0;

const manualReviewItems = finalItems.filter(it => !it.itemResolved);
const needsManualReview = manualReviewItems.length > 0;

const allWarnings = allChunks.flatMap(c => c._meta?.warnings ?? []);

// Envelope fields (senderEmail, customerId, workflowRunId, etc.) are
// identical across all chunks since they came from the same submission —
// take them from the first chunk, but overwrite parseConfidence with the
// recombined value.
const baseEnvelope = allChunks[0].envelope ?? {};

const workingObject = {
  envelope: {
    ...baseEnvelope,
    parseConfidence
  },
  customer:         null,
  items:            finalItems,
  openOrders:       [],
  availability:     [],
  topItems:         [],
  comparison:       null,
  salesHistory:     null,
  aiRecommendation: null,
  _meta: {
    stage1CompletedAt:    new Date().toISOString(),
    itemCount:            finalItems.length,
    reportDate:           allChunks[0]._meta?.reportDate ?? new Date().toISOString().split('T')[0],
    manualReviewRequired: needsManualReview,
    manualReviewCount:    manualReviewItems.length,
    warnings:             allWarnings,
    processingNotes:      allWarnings.length > 0 ? allWarnings.join(' | ') : null,
    chunksProcessed:      allChunks.length
  }
};

return { json: workingObject };
